import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

n, m = read_ints()
graph = defaultdict(list)

for _ in range(m):
    u, v = read_ints()
    graph[u].append(v)
    graph[v].append(u)

for node in graph:
    graph[node].sort()

visited = [False] * (n + 1)
path = []

def dfs(node):
    visited[node] = True
    path.append(node)
    for neighbor in graph[node]:
        if not visited[neighbor]:
            dfs(neighbor)
            path.append(node)

dfs(1)

print(' '.join(map(str, path)))
